package net.officefloor.hq.app.rate;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Sets a rate per imported line, in order, as the rate form would: each replaces the grade's rate for
 * the same from-date, and is audited (RATE_SET), then the figures it moved. Every line was checked
 * first, so a refused import writes nothing.
 */
public class SetImportedRates {
    public void set(@Val Sheet sheet, @Val ImportRatesLines lines, RateRepository rates, PersonRepository people,
            SheetRepository sheets, ClaimRepository claims, SettingsRepository settings, HttpServletRequest request,
            Audit audit, Out<ImportRatesResponse> result) {
        String user = Audit.user(request);
        Rollup before = Rollup.of(sheet.id(), sheet.today(), people, claims, rates, settings.find(sheet.id()));
        for (RateInput input : lines.lines()) {
            Rate rate = new Rate(sheet.id(), input.grade(), input.pct(), input.from(), input.to());
            rates.save(rate);
            new AuditRateSet().audit(sheet, rate, request, audit);
            Rollup after = Rollup.of(sheet.id(), sheets.today(sheet.id()), people, claims, rates,
                    settings.find(sheet.id()));
            after.changesSince(before, sheet.id(), user).forEach(audit::record);
            before = after;
        }
        result.set(new ImportRatesResponse(lines.lines().size()));
    }
}
package net.officefloor.hq.app.rate;

import java.util.ArrayList;
import java.util.List;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Splits the import into lines (blank lines skipped) and checks each by the rate form's rules; the
 * first line that fails refuses the whole import. An import with no lines is refused too.
 */
public class ValidateImportRates {
    public void validate(@RequestBody ImportRatesRequest request, Out<ImportRatesLines> linesOut)
            throws InvalidRateException {
        String text = request == null || request.text() == null ? "" : request.text();
        List<RateInput> lines = new ArrayList<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n|\\r")) {
            number++;
            if (raw.isBlank()) continue;
            String[] fields = raw.split(",", -1);
            if (fields.length < 2 || fields.length > 4) {
                throw new InvalidRateException("Line " + number + ": grade,rate,from,to");
            }
            String from = fields.length > 2 ? fields[2] : "";
            String to = fields.length > 3 ? fields[3] : "";
            try {
                lines.add(RateRequest.checked(new RateRequest(fields[0], fields[1], from, to)));
            } catch (InvalidRateException e) {
                throw new InvalidRateException("Line " + number + ": " + e.getMessage());
            }
        }
        if (lines.isEmpty()) throw new InvalidRateException("Paste at least one line of grade,rate,from,to");
        linesOut.set(new ImportRatesLines(lines));
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import jakarta.servlet.http.HttpServletRequest;

/** Records the saved rate. Runs after every rule has passed, so a refused change writes nothing. */
public class AuditRateSet {
    public void audit(@Val Sheet sheet, @Val Rate rate, HttpServletRequest request, Audit audit) {
        audit.record("RATE_SET sheet=" + sheet.id() + " by=" + Audit.user(request)
                + " grade=" + rate.grade() + " rate=" + rate.pct().toPlainString()
                + (rate.from() == null ? "" : " from=" + rate.from())
                + (rate.to() == null ? "" : " to=" + rate.to()));
    }
}

