-- Each person's carried figure for a closed (or soft-closed) period, fixed when the period was
-- closed (one row per person on the sheet at that moment), as their due-total for it is. A person
-- with no row shows 0.00 for the closed period. Removed when the period is reopened, making the
-- figures live again.
CREATE TABLE period_person_carried (
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet(id),
    period_name VARCHAR(200) NOT NULL,
    person_id BIGINT NOT NULL,
    carried DECIMAL(19, 2) NOT NULL,
    PRIMARY KEY (sheet_id, period_name, person_id)
);
package net.officefloor.hq.app.period;

import jakarta.servlet.http.HttpServletRequest;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.AsOf;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/**
 * The sheet's periods, by from-date. Read as of a date, as they stood then: a period closed then
 * shows the people's figures and carried figures fixed by the close it is still in now (none when it has since been
 * reopened or closed again with another due-total).
 */
public class RespondWithPeriods {
    public void respond(@Val Sheet sheet, PeriodRepository repository, SettingsRepository settingsRepository, HttpServletRequest request,
            ObjectResponse<PeriodsResponse> response) {
        LocalDate asOf = AsOf.of(request);
        Map<String, Map<Long, BigDecimal>> personTotals = repository.personTotals(sheet.id());
        Map<String, Map<Long, BigDecimal>> personCarried = repository.personCarried(sheet.id());
        List<Period> periods = repository.findAll(sheet.id());
        if (asOf != null) {
            Map<String, Period> now = new HashMap<>();
            periods.forEach((p) -> now.put(p.name(), p));
            periods = repository.findAllAsOf(sheet.id(), asOf);
            Map<String, Map<Long, BigDecimal>> thenTotals = new HashMap<>();
            Map<String, Map<Long, BigDecimal>> thenCarried = new HashMap<>();
            for (Period p : periods) {
                Period current = now.get(p.name());
                if (p.closed() && current != null && current.closed() && same(p.closedTotal(), current.closedTotal())) {
                    thenTotals.put(p.name(), personTotals.getOrDefault(p.name(), Map.of()));
                    thenCarried.put(p.name(), personCarried.getOrDefault(p.name(), Map.of()));
                }
            }
            personTotals = thenTotals;
            personCarried = thenCarried;
        }
        Map<String, Map<Long, BigDecimal>> totals = personTotals;
        Map<String, Map<Long, BigDecimal>> carried = personCarried;
        Settings settings = settingsRepository.find(sheet.id());
        response.send(new PeriodsResponse(periods.stream()
                .map(p -> PeriodResponse.from(p, totals.getOrDefault(p.name(), Map.of()),
                        carried.getOrDefault(p.name(), Map.of()), settings)).toList()));
    }

    private static boolean same(BigDecimal a, BigDecimal b) {
        return a == null ? b == null : b != null && a.compareTo(b) == 0;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;
import net.officefloor.hq.app.setting.Settings;

/**
 * A period, as the screen reads it: its name, its from and to dates (yyyy-MM-dd), whether it is
 * closed, the due-total fixed when it was closed ("" while open), and each person's due-total fixed
 * when it was closed, by person id (empty while open), and whether it is soft-closed (closed, its
 * claims still open to change), and the fiscal year its from-date falls in (FY<yyyy>), and its cap
 * ("" for none), and each person's carried figure fixed when it was closed, by person id (empty while open).
 */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> personTotals, boolean soft, String fy, String cap, Map<String, String> personCarried) {
    public static PeriodResponse from(Period period, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
            Settings settings) {
        Map<String, String> totals = new LinkedHashMap<>();
        personTotals.forEach((id, total) -> totals.put(String.valueOf(id), total.setScale(2).toPlainString()));
        Map<String, String> carried = new LinkedHashMap<>();
        personCarried.forEach((id, figure) -> carried.put(String.valueOf(id), figure.setScale(2).toPlainString()));
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString(),
                period.closed(), period.closedTotal() == null ? "" : period.closedTotal().setScale(2).toPlainString(),
                totals, period.soft(), settings.fiscalYearOf(period.from()),
                period.cap() == null ? "" : String.valueOf(period.cap()), carried);
    }
}
